<script setup>
import { onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { api } from '../../lib/api.js'; import { hasPermission } from '../../lib/auth.js'; const route=useRoute(),router=useRouter(); const rows=ref([]),total=ref(0),dialog=ref(false),editing=ref(null),categories=ref([]),brands=ref([]),units=ref([]); const query=reactive({page:1,size:20,code:'',name:'',model:'',productType:'',status:null}); const form=reactive({productCode:'',productName:'',categoryId:null,brandId:null,model:'',specification:'',unitId:null,productType:'QUANTITY',trackSn:false,trackMac:false,isFixedAsset:false,enableQrcode:false,safetyStock:0,minStock:0,maxStock:0,remark:'',status:true}); async function load(){try{const d=await api.products(query);rows.value=d.list;total.value=d.total;categories.value=(await api.categories()).flatMap(function f(x){return x.reduce((a,v)=>a.concat(v,f(v.children||[])),[])});brands.value=await api.brandOptions();units.value=await api.unitOptions()}catch(e){ElMessage.error(e.message)}} function open(x=null){editing.value=x?.id||null;Object.assign(form,x||{productCode:'',productName:'',categoryId:null,brandId:null,model:'',specification:'',unitId:null,productType:'QUANTITY',trackSn:false,trackMac:false,isFixedAsset:false,enableQrcode:false,safetyStock:0,minStock:0,maxStock:0,remark:'',status:true});dialog.value=true} async function save(){try{editing.value?await api.updateProduct(editing.value,form):await api.createProduct(form);dialog.value=false;await load()}catch(e){ElMessage.error(e.message)}} onMounted(async()=>{if(route.query.id){try{const product=await api.product(Number(route.query.id));query.code=product.productCode}catch(e){ElMessage.error(e.message)}}await load()})
</script><template><div class="page-heading"><h1>物资档案</h1><el-button v-if="hasPermission('system.product.create')" type="primary" @click="open()">新增物资</el-button></div><el-card><el-form inline><el-input v-model="query.code" placeholder="编号"/><el-input v-model="query.name" placeholder="名称"/><el-input v-model="query.model" placeholder="型号"/><el-select v-model="query.productType" clearable placeholder="类型"><el-option label="数量型" value="QUANTITY"/><el-option label="设备型" value="DEVICE"/></el-select><el-button @click="query.page=1;load()">查询</el-button></el-form><el-table :data="rows"><el-table-column prop="productCode" label="编号"/><el-table-column prop="productName" label="名称"/><el-table-column prop="categoryName" label="分类"/><el-table-column prop="brandName" label="品牌"/><el-table-column prop="model" label="型号"/><el-table-column prop="productType" label="类型"/><el-table-column label="状态"><template #default="{row}">{{row.status?'启用':'停用'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="hasPermission('asset.qr.view') && hasPermission('asset.qr.generate')" link @click="router.push({ path: '/assets/qr', query: { productId: row.id } })">二维码</el-button><el-button v-if="hasPermission('system.product.update')" link @click="open(row)">编辑</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" :total="total" @current-change="load"/></el-card><el-dialog v-model="dialog" :title="editing?'编辑物资':'新增物资'" width="620px"><el-form label-width="100px"><el-form-item label="编号"><el-input v-model="form.productCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.productName"/></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId"><el-option v-for="x in categories.filter(x=>x.status)" :key="x.id" :label="x.categoryName" :value="x.id"/></el-select></el-form-item><el-form-item label="品牌"><el-select v-model="form.brandId"><el-option v-for="x in brands" :key="x.id" :label="x.brandName" :value="x.id"/></el-select></el-form-item><el-form-item label="单位"><el-select v-model="form.unitId"><el-option v-for="x in units" :key="x.id" :label="x.unitName" :value="x.id"/></el-select></el-form-item><el-form-item label="类型"><el-radio-group v-model="form.productType"><el-radio value="QUANTITY">数量型</el-radio><el-radio value="DEVICE">设备型</el-radio></el-radio-group></el-form-item><el-form-item label="型号"><el-input v-model="form.model"/></el-form-item><el-form-item label="规格"><el-input v-model="form.specification"/></el-form-item><el-form-item label="管理属性"><el-checkbox v-model="form.trackSn">SN管理</el-checkbox><el-checkbox v-model="form.trackMac">MAC管理</el-checkbox><el-checkbox v-model="form.isFixedAsset">固定资产</el-checkbox><el-checkbox v-model="form.enableQrcode">启用二维码</el-checkbox></el-form-item><el-form-item label="库存配置"><el-input-number v-model="form.safetyStock" :min="0"/><el-input-number v-model="form.minStock" :min="0"/><el-input-number v-model="form.maxStock" :min="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
